alter table public.sentence_option
 add column review_status text not null default 'draft' check(review_status in ('draft','approved','held','rejected')),
 add column reason_ko text,
 add constraint approved_sentence_option_reason check(review_status<>'approved' or length(btrim(coalesce(reason_ko,'')))>0);
-- Existing v1 content is retained for provenance but never mixed into the v2 bank.
update public.sentence set status='inactive',updated_at=now() where batch='sentence-bank-v1';
update public.sentence_option set review_status='rejected',reason_ko='구버전 후보. 문맥 기준 후보 풀로 대체됨.'
where socket_id in (select sk.id from public.sentence_socket sk join public.sentence s on s.id=sk.sentence_id where s.batch='sentence-bank-v1');
drop policy option_published_read on public.sentence_option;
create policy option_published_read on public.sentence_option for select to authenticated using(
 review_status='approved' and exists(select 1 from public.sentence_socket sk join public.sentence s on s.id=sk.sentence_id where sk.id=socket_id and s.status='published')
);
create temporary table contextual_import(data jsonb) on commit drop;

insert into contextual_import values ($bank$[{"id":"reading-v2-001","text":"配布前の資料に誤字が見つかりました。まず誤字を修正します。参加者に届けるため、直した版だけを送ります。","translation":"배포 전 자료에서 오탈자가 발견되었습니다. 먼저 오탈자를 고칩니다. 수정한 판만 참가자에게 보냅니다.","sockets":[{"original":"修正します","start":23,"options":[{"text":"修正します","word":"修正","accepted":true,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 표현은 '오류를 고침'라는 뜻으로 단서와 일치합니다."},{"text":"訂正します","word":"訂正","accepted":true,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 표현은 '오류를 고침'라는 뜻으로 단서와 일치합니다."},{"text":"複製します","word":"複製","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '오류를 포함해 복제'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"放置します","word":"放置","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '그대로 둠'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"拡大します","word":"拡大","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '오류를 확대'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"転送します","word":"転送","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '오류를 보냄'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]},{"original":"送ります","start":46,"options":[{"text":"送ります","word":"送る","accepted":true,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 표현은 '수신자에게 보냄'라는 뜻으로 단서와 일치합니다."},{"text":"送付します","word":"送付","accepted":true,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 표현은 '수신자에게 보냄'라는 뜻으로 단서와 일치합니다."},{"text":"削除します","word":"削除","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '삭제'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"手元に残します","word":"手元に残","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '자기 손에만 보관'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"破棄します","word":"破棄","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '폐기'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"保管するだけにします","word":"保管するだけに","accepted":false,"reason":"오탈자는 고치고 수정본을 전달해야 함。이 후보는 '보관만 함'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]}]},{"id":"reading-v2-002","text":"定員十人に対して二十人が申し込みました。全員が座れるように席を増やします。空間を作るため、部屋の不要な棚を取り除きます。","translation":"정원 10명인데 20명이 신청했습니다. 모두 앉을 수 있도록 좌석을 늘립니다. 공간을 만들려고 불필요한 선반을 방에서 치웁니다.","sockets":[{"original":"増やします","start":31,"options":[{"text":"増やします","word":"増やす","accepted":true,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 표현은 '수량을 늘림'라는 뜻으로 단서와 일치합니다."},{"text":"増加させます","word":"増加させます","accepted":true,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 표현은 '수량을 늘림'라는 뜻으로 단서와 일치합니다."},{"text":"減らします","word":"減らす","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '수량 감소'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"維持します","word":"維持","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '수량 유지'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"半分にします","word":"半分に","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '수량을 절반으로 줄임'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"ゼロにします","word":"ゼロに","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '수량을 0으로 만듦'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]},{"original":"取り除きます","start":53,"options":[{"text":"取り除きます","word":"取り除く","accepted":true,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 표현은 '불필요한 항목을 제거함'라는 뜻으로 단서와 일치합니다."},{"text":"除去します","word":"除去","accepted":true,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 표현은 '불필요한 항목을 제거함'라는 뜻으로 단서와 일치합니다."},{"text":"追加します","word":"追加","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '항목 추가'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"付け加えます","word":"付け加えます","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '더함'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"増やします","word":"増やす","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '늘림'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"残します","word":"残","accepted":false,"reason":"20명을 수용할 좌석 증설과 불필요한 선반 제거가 필요함。이 후보는 '남김'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]}]},{"id":"reading-v2-003","text":"注文が百件から五十件になりました。在庫を余らせないため生産数を減らします。売れ残りは半額で売ると決まったので、その価格も値下げします。","translation":"주문이 100건에서 50건이 되었습니다. 재고가 남지 않도록 생산량을 줄입니다. 팔리지 않은 상품 가격도 내립니다.","sockets":[{"original":"減らします","start":31,"options":[{"text":"減らします","word":"減らす","accepted":true,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 표현은 '수량을 줄임'라는 뜻으로 단서와 일치합니다."},{"text":"削減します","word":"削減","accepted":true,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 표현은 '수량을 줄임'라는 뜻으로 단서와 일치합니다."},{"text":"増やします","word":"増やす","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '수량 증가'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"維持します","word":"維持","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '수량 유지'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"倍にします","word":"倍に","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '수량을 두 배로 늘림'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"最大にします","word":"最大に","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '수량을 최대로 만듦'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]},{"original":"値下げします","start":60,"options":[{"text":"値下げします","word":"値下げ","accepted":true,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 표현은 '가격을 낮춤'라는 뜻으로 단서와 일치합니다."},{"text":"安くします","word":"安く","accepted":true,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 표현은 '가격을 낮춤'라는 뜻으로 단서와 일치합니다."},{"text":"値上げします","word":"値上げ","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '가격 인상'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"高くします","word":"高く","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '가격을 높임'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"据え置きます","word":"据え置きます","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '가격 유지'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"倍にします","word":"倍に","accepted":false,"reason":"주문 감소에 맞춘 감산이며 재고 판매를 위한 가격 인하임。이 후보는 '가격을 두 배로 함'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]}]},{"id":"reading-v2-004","text":"開始予定は十時ですが、先方は九時からしか参加できません。開始時刻を九時に早めます。変更した時刻を全員に知らせます。","translation":"시작 예정은 10시지만 상대방은 9시부터만 참석할 수 있습니다. 시작 시각을 9시로 앞당깁니다. 변경 시각을 전원에게 알립니다.","sockets":[{"original":"早めます","start":36,"options":[{"text":"早めます","word":"早める","accepted":true,"reason":"10시를 9시로 변경하며 전원에게 변경 사실을 알려야 함。이 표현은 '예정 시각을 앞당김'라는 뜻으로 단서와 일치합니다."},{"text":"前倒しします","word":"前倒し","accepted":true,"reason":"10시를 9시로 변경하며 전원에게 변경 사실을 알려야 함。이 표현은 '예정 시각을 앞당김'라는 뜻으로 단서와 일치합니다."},{"text":"遅らせます","word":"遅らせる","accepted":false,"reason":"10시를 9시로 변경하며 전원에게 변경 사실을 알려야 함。이 후