수란 추가와 의무 입력 안내가 필요함。이 표현은 '반드시 해야 하는 필수 사항'라는 뜻으로 단서와 일치합니다."},{"text":"義務","word":"義務","accepted":true,"reason":"누락된 필수란 추가와 의무 입력 안내가 필요함。이 표현은 '반드시 해야 하는 필수 사항'라는 뜻으로 단서와 일치합니다."},{"text":"任意","word":"任意","accepted":false,"reason":"누락된 필수란 추가와 의무 입력 안내가 필요함。이 후보는 '선택 사항'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"自由","word":"自由","accepted":false,"reason":"누락된 필수란 추가와 의무 입력 안내가 필요함。이 후보는 '자유 선택'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"不要","word":"不要","accepted":false,"reason":"누락된 필수란 추가와 의무 입력 안내가 필요함。이 후보는 '필요 없음'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"禁止","word":"禁止","accepted":false,"reason":"누락된 필수란 추가와 의무 입력 안내가 필요함。이 후보는 '하면 안 됨'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]}]},{"id":"reading-v2-100","text":"診療を受ける前に問診票が必要で、未記入では受付できません。記入は診療の前に済ませます。記入を終えた問診票は受付が集めます。","translation":"진료 전에 문진표가 필요하며 미기입 상태로는 접수할 수 없습니다. 기입은 진료 전에 끝냅니다. 작성한 문진표는 접수처에서 회수합니다.","sockets":[{"original":"前","start":35,"options":[{"text":"前","word":"前","accepted":true,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 표현은 '특정 시점 이전'라는 뜻으로 단서와 일치합니다."},{"text":"直前","word":"直前","accepted":true,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 표현은 '특정 시점 이전'라는 뜻으로 단서와 일치합니다."},{"text":"後","word":"後","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '이후'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"翌日","word":"翌日","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '다음 날'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"直後","word":"直後","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '직후'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"翌週","word":"翌週","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '다음 주'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]},{"original":"集めます","start":56,"options":[{"text":"集めます","word":"集める","accepted":true,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 표현은 '여러 사람의 서류를 모음'라는 뜻으로 단서와 일치합니다."},{"text":"回収します","word":"回収","accepted":true,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 표현은 '여러 사람의 서류를 모음'라는 뜻으로 단서와 일치합니다."},{"text":"配ります","word":"配る","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '나누어 줌'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"配布します","word":"配布","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '배포'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"返します","word":"返す","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '돌려줌'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."},{"text":"返却します","word":"返却","accepted":false,"reason":"진료 전에 작성해야 하며 작성한 서류는 접수처가 회수함。이 후보는 '반납'라는 뜻이므로 이 지문의 지시·사실과 맞지 않습니다."}]}]}]$bank$::jsonb);
insert into public.sentence(id,text_ja,translation_ko,status,batch)
select j->>'id',j->>'text',j->>'translation','published','sentence-bank-v2-context'
from contextual_import,jsonb_array_elements(data) j;
insert into public.sentence_socket(sentence_id,start_offset,end_offset,original_text)
select j->>'id',(k->>'start')::integer,(k->>'start')::integer+length(k->>'original'),k->>'original'
from contextual_import,jsonb_array_elements(data) j,jsonb_array_elements(j->'sockets') k;
with unambiguous_words as (
 select term,(array_agg(id))[1] as id,(array_agg(kana))[1] as kana
 from public.word where deleted_at is null and entry_type='word' group by term having count(*)=1
)
insert into public.sentence_option(socket_id,word_id,display_text,reading,is_accepted,review_status,reason_ko)
select sk.id,w.id,o->>'text',case when w.term=o->>'text' then w.kana else null end,
 (o->>'accepted')::boolean,'approved',o->>'reason'
from contextual_import cross join lateral jsonb_array_elements(data) j
cross join lateral jsonb_array_elements(j->'sockets') k cross join lateral jsonb_array_elements(k->'options') o
join public.sentence_socket sk on sk.sentence_id=j->>'id' and sk.start_offset=(k->>'start')::integer
left join unambiguous_words w on w.term=o->>'word';
